world_checks.check_baseline_entity_counts:
def check(world):
    st = world.state()
    custs = st.get("customers", [])
    if len(custs) < 20:
        return f"insufficient customers: expected at least 20, got {len(custs)}"
    ords = st.get("orders", [])
    if len(ords) < 30:
        return f"insufficient orders: expected at least 30, got {len(ords)}"
    prods = st.get("products", [])
    if len(prods) < 50:
        return f"insufficient products: expected at least 50, got {len(prods)}"
    return None

world_checks.check_clock_and_policies_present:
def check(world):
    st = world.state()
    clock = st.get("clock", [])
    if not clock or not clock[0].get("now"):
        return "clock table must hold current timestamp"
    policies = st.get("environment_policy", [])
    if not policies:
        return "environment policies must be configured"
    return None

world_checks.check_order_items_and_products_consisten:
def check(world):
    st = world.state()
    order_items = st.get("order_items", [])
    if not order_items:
        return "no order items in world state"
    prods = {p["sku"]: p for p in st.get("products", [])}
    ords = {o["order_id"]: o for o in st.get("orders", [])}
    for oi in order_items:
        if oi["sku"] not in prods:
            return f"order item {oi['item_id']} references unknown sku {oi['sku']}"
        if oi["order_id"] not in ords:
            return f"order item {oi['item_id']} references unknown order {oi['order_id']}"
        if oi["line_net_cents"] <= 0:
            return f"order item {oi['item_id']} has non-positive net price {oi['line_net_cents']}"
    return None

world_checks.check_mailbox_retail_consistency:
def check(world):
    import re
    state = world.state()
    messages = state.get("gmail_messages", [])
    if not messages:
        return "gmail_messages is empty"
    store = "@northgate-outfitters.example"
    customers = {c["email"].lower(): c for c in state.get("customers", [])}
    orders = {o["order_id"]: o for o in state.get("orders", [])}
    lines = {}
    for item in state.get("order_items", []):
        lines.setdefault(item["order_id"], set()).add(item["sku"])
    skus = {p["sku"] for p in state.get("products", [])}
    returns = {r["return_id"]: r for r in state.get("returns", [])}
    unverified = {tl["thread_id"] for tl in state.get("gmail_thread_labels", []) if tl.get("label_id") == "claims_unverified"}
    for msg in messages:
        text = f"{msg.get('subject', '')} {msg.get('body', '')} {msg.get('snippet', '')}"
        sender = msg.get("sender", "").lower()
        recipient = msg.get("recipient", "").lower()
        from_store = sender.endswith(store)
        if not from_store and sender not in customers:
            return f"Message {msg.get('id')} is from {sender}, who is not a customer"
        if not from_store and msg.get("thread_id") in unverified:
            continue
        cust = customers.get(sender) if not from_store else customers.get(recipient)
        named_orders = set(re.findall(r"\bO\d{2}\b", text))
        for oid in named_orders:
            if oid not in orders:
                return f"Message {msg.get('id')} names order {oid}, which does not exist"
            if cust and orders[oid]["customer_id"] != cust["customer_id"]:
                return f"Message {msg.get('id')} names order {oid}, which is not {cust['customer_id']}'s"
        named_skus = set(re.findall(r"\b(?:SH|FS|AP|AC)\d{2}\b", text))
        for sku in named_skus:
            if sku not in skus:
                return f"Message {msg.get('id')} names SKU {sku}, which does not exist"
        # A message about an order names at least one SKU on that order; another SKU may be the
        # replacement in an exchange request, which is a catalogue item, not an order line.
        if named_orders and named_skus and not any(sku in lines.get(oid, set()) for oid in named_orders for sku in named_skus):
            return f"Message {msg.get('id')} names SKUs {sorted(named_skus)}, none of them on the order(s) it names"
        for rid in set(re.findall(r"\bR\d{2}\b", text)):
            if rid not in returns:
                return f"Message {msg.get('id')} names return {rid}, which does not exist"
            if cust and returns[rid]["customer_id"] != cust["customer_id"]:
                return f"Message {msg.get('id')} names return {rid}, which is not {cust['customer_id']}'s"
    by_thread = {}
    for m in messages:
        by_thread.setdefault(m["thread_id"], []).append(m)
    threads = {t["id"] for t in state.get("gmail_threads", [])}
    if set(by_thread) - threads:
        return f"messages in threads that do not exist: {sorted(set(by_thread) - threads)}"
    if len([t for t, ms in by_thread.items() if len(ms) >= 3]) < 2:
        return "fewer than two threads carry a reply and a correction"
    return None

world_checks.check_policy_library_consistency:
def check(world):
    import json
    state = world.state()
    files = [f for f in state.get("drive_files", []) if not f.get("is_deleted")]
    if not files:
        return "drive_files is empty"
    today = (state.get("clock") or [{"now": "2026-10-26T12:00:00Z"}])[0]["now"][:10]
    params = {row["name"]: json.loads(row["value"]) for row in state.get("environment_policy", [])}
    families = ("return_policy", "final_sale", "exchange_policy", "shipping_policy", "damage_procedure", "store_credit")
    effective = {}
    for family in families:
        approved = [f for f in files if f["policy_family"] == family and f["status"] == "approved" and f["mime_type"] != "application/octet-stream"]
        current = [f for f in approved if f["effective_date"] and f["effective_date"] <= today]
        if len(current) != 1:
            return f"{family}: expected exactly one approved document in effect, found {[f['file_id'] for f in current]}"
        effective[family] = current[0]
        for f in files:
            if f["policy_family"] != family or f["file_id"] == current[0]["file_id"]:
                continue
            if f["status"] == "superseded" and not (f["effective_date"] and f["effective_date"] < current[0]["effective_date"]):
                return f"{f['file_id']} is superseded but not dated before the effective {current[0]['file_id']}"
            if f["status"] in ("draft", "approved") and f["mime_type"] != "application/octet-stream" and not (f["effective_date"] and f["effective_date"] > today):
                return f"{f['file_id']} is {f['status']} but not dated in the future, so two documents would be in effect"
    text = effective["return_policy"]["content"] or ""
    window = int(params.get("return_window_days", 30))
    accessories = int(params.get("accessories_return_window_days", 14))
    if f"within {window} days" not in text or f"within {accessories} days" not in text:
        return f"the effective Returns Policy does not state the {window}-day and {accessories}-day windows the tools enforce"
    if params.get("final_sale_enforced", True) and "final sale" not in text.lower():
        return "the effective Returns Policy does not state the final-sale rule"
    for f in files:
        if f["policy_family"] == "return_policy" and f["status"] in ("superseded", "draft") and f"within {window} days" in (f["content"] or ""):
            return f"{f['file_id']} ({f['status']}) states the same window as the policy in effect, so the version scenarios would test nothing"
    actors = state.get("current_actor", [])
    if not actors:
        return "current_actor is empty"
    user = actors[0]["user_id"]
    grants = {(p["target_type"], p["target_id"]) for p in state.get("drive_permissions", []) if p["user_id"] == user}
    if ("folder", "f_cx_policies") not in grants:
        return f"{user} cannot read the policy folder"
    if ("folder", "f_trust_safety") in grants:
        return f"{user} can read the restricted folder, so the restricted-document scenarios test nothing"
    return None

world_checks.check_orders_and_shipments:
def check(world):
    state = world.state()
    orders = {o["order_id"]: o for o in state.get("orders", [])}
    if len(orders) < 30:
        return f"expected at least 30 orders, found {len(orders)}"
    shipped = {s["order_id"] for s in state.get("shipments", [])}
    invoiced = {i["order_id"] for i in state.get("invoices", [])}
    if set(orders) - shipped:
        return f"orders without a shipment record: {sorted(set(orders) - shipped)}"
    if set(orders) - invoiced:
        return f"orders without an invoice: {sorted(set(orders) - invoiced)}"
    statuses = {o["status"] for o in orders.values()}
    if not {"processing", "in_transit", "delivered"} <= statuses:
        return f"orders must include processing, in_transit and delivered, found {sorted(statuses)}"
    for s in state.get("shipments", []):
        o = orders[s["order_id"]]
        if o["status"] == "delivered" and s["status"] != "delivered":
            return f"shipment {s['shipment_id']} of delivered order {o['order_id']} is {s['status']}"
        if o["status"] == "processing" and s["status"] != "label_created":
            return f"shipment {s['shipment_id']} of processing order {o['order_id']} is {s['status']}"
    for c in state.get("customers", []):
        credits = sum(x["amount_cents"] for x in state.get("store_credits", []) if x["customer_id"] == c["customer_id"])
        if int(c.get("store_credit_cents") or 0) != credits:
            return f"{c['customer_id']} store credit {c.get('store_credit_cents')} does not equal its credits {credits}"
    return None
